function Value_change_gwl(selectElement, index) {
    var selectedValue = $(selectElement).val();
    if (selectedValue == "Others") {
        $("#Hide_AWP1_TR" + index).find("#other_well_type" + index).prop("disabled", false);

    }
    else {
        $("#Hide_AWP1_TR" + index).find("#other_well_type" + index).prop("disabled", true);
    }

}

function Value_change_Ownership(selectElement, index) {
    var selectedValue = $(selectElement).val();
    if (selectedValue == "Government") {
        $("#Hide_AWP1_TR" + index).find("#source_Ownership_type" + index).empty();
        $("#Hide_AWP1_TR" + index).find("#source_Ownership_type" + index).prop("disabled", false);
        let data = [{ Text: "CGWB", Value: "CGWB" }, { Text: "SGWB", Value: "SGWB" }, { Text: "Others", Value: "Others" }];
        $.each(data, function (key, value) {
            $("#Hide_AWP1_TR" + index).find("#source_Ownership_type" + index).append($('<option>').text(value.Text).attr('value', value.Value));
        });
    } else {

        //id="Other_Source_type' + i + '" 
        $("#Hide_AWP1_TR" + index).find("#Other_Source_type" + index).css('display', 'none');
        $("#Hide_AWP1_TR" + index).find("#source_Ownership_type" + index).prop("disabled", true);
        $("#Hide_AWP1_TR" + index).find("#source_Ownership_type" + index).empty();

    }

}
