function Update_data(id, RowNo) {         //abhi2906

    var i = 0;
    var id = id;
    var state = $('#state' + RowNo).val();
    var district = $('#district' + RowNo).val();
    var block = $('#block' + RowNo).val();
    var grampanchayat = $('#grampanchayat' + RowNo).val();
    var sitename = $('#sitename' + RowNo).val();
    var locationdetails = $('#locationdetails' + RowNo).val();
    var latitude = $('#latitude' + RowNo).val();
    var longitude = $('#longitude' + RowNo).val();
    var gwl_date = $('#gwl_date' + RowNo).val();
    var wellid = $('#wellid' + RowNo).val();
    var typeofwell = $('#typeofwell' + RowNo).val();
    var other_well_type = $('#other_well_type' + RowNo).val();
    var source_Ownership = $('#source_Ownership' + RowNo).val();
    var source_Ownership_type = $('#source_Ownership_type' + RowNo).val();
    var source_Ownership_type_other = $('#source_Ownership_type_other' + RowNo).val();
    var Diameter_of_Well = $('#Diameter_of_Well' + RowNo).val();
    var welldepth = $('#welldepth' + RowNo).val();
    var Height_of_Measuring_Point = $('#Height_of_Measuring_Point' + RowNo).val();


    if (sitename == "" || sitename == null) {

        alert("Please Enter Village Name ");
        i = 1;
    }
    else if (locationdetails == "" || locationdetails == null) {

        alert("Please Enter Location Details");
        i = 1;
    }
    else if (latitude == "") {
        alert("Please Enter latitude");
        i = 1;
    }
    else if (longitude == "") {

        alert("Please Enter longitude");
        i = 1;
    }
    else if (Diameter_of_Well == "") {

        alert("Please Enter Diameter of well(m)");
        i = 1;
    }
    else if (welldepth == "") {

        alert("Please Enter Depth of Well(mbmp)");
        i = 1;
    }
    else if (Height_of_Measuring_Point == "") {

        alert("Please Enter Height of Measuring Point(magl)");
        i = 1;
    }

    else if (source_Ownership_type == "Others" && source_Ownership_type_other == "" || source_Ownership_type_other == null) {

        alert("Please Enter Other Government Source");
        i = 1;
    }




    if (i == 0) {

        if (confirm("Are you sure you want to Update this entry?")) {
            var formdata = new FormData();
            formdata.append("id", id);
            formdata.append("sitename", sitename);
            formdata.append("locationdetails", locationdetails);
            formdata.append("latitude", latitude);
            formdata.append("longitude", longitude);
            formdata.append("Diameter_of_Well", Diameter_of_Well);
            formdata.append("welldepth", welldepth);
            formdata.append("Height_of_Measuring_Point", Height_of_Measuring_Point);
            formdata.append("typeofwell", typeofwell);
            formdata.append("other_well_type", other_well_type);
            formdata.append("source_Ownership", source_Ownership);
            formdata.append("source_Ownership_type", source_Ownership_type);
            formdata.append("source_Ownership_type_other", source_Ownership_type_other);


            $.ajax({
                url: '/GplevelMobileData/Update_gwl',
                data: formdata,
                type: 'POST',
                contentType: false,
                processData: false,
                success: function (response) {

                    alert(response);
                    if (response == "SessionTimeOut") {
                          window.location = "/Home/LogOut";
                    }
                    else if (response == "Updated Successfully") {
                        PageNumberexe = PageNumberexe;
                        if (PageNumberexe == 1) {
                            snoexe = 0;
                        } else {
                            snoexe -= close_length;
                        }
                        exetotal = 0;
                        totalexess = 0;
                        totalexe();
                    }
                    else {
                        $('.loader').hide();
                    }
                },
                error: function () {
                    alert('Update Failed');
                }
            });
        }
    }
}
