function enforceNumberValidation_waterflow(i, ele) {

    let j = i.toString();
    /*var i = aaa;*/
    var match = false;
    var match2 = false;
    var matchwr = false;
    var matchwr2 = false;
    var lat = $('#latitude_waterflow' + j).val();
    var long = $('#longitude_waterflow' + j).val();




    if (!(lat.indexOf(".") == -1)) {
        match = true; // decimal
    } else {
        match = false;
    }
    if (lat.length == 2 && match != true) {
        $('#latitude_waterflow' + j).val(lat + '.');
    } else if (lat.length == 1 && match != false) {
        $('#latitude_waterflow' + j).val('');
    }


    if (!(long.indexOf(".") == -1)) {
        match2 = true; // decimal
    } else {
        match2 = false;
    }
    if (long.length == 2 && match2 != true) {
        $('#longitude_waterflow' + j).val(long + '.');
    } else if (long.length == 1 && match2 != false) {
        $('#longitude_waterflow' + j).val('');
    }


    var latwr = $('#latitude_waterflow' + j).val();
    var longwr = $('#longitude_waterflow' + j).val();

    if (!(latwr.indexOf(".") == -1)) {
        matchwr = true; // decimal
    } else {
        matchwr = false;
    }
    if (latwr.length == 2 && matchwr != true) {
        $('#latitude_waterflow' + j).val(latwr + '.');
    } else if (latwr.length == 1 && matchwr != false) {
        $('#latitude_waterflow' + j).val('');
    }


    if (!(longwr.indexOf(".") == -1)) {
        matchwr2 = true; // decimal
    } else {
        matchwr2 = false;
    }
    if (longwr.length == 2 && matchwr2 != true) {
        $('#longitude_waterflow' + j).val(longwr + '.');
    } else if (longwr.length == 1 && matchwr2 != false) {
        $('#longitude_waterflow' + j).val('');
    }


    if ($(ele).data('decimal') != null) {
        // found valid rule for decimal
        var decimal = parseInt($(ele).data('decimal')) || 0;
        var val = $(ele).val();
        if (decimal > 0) {
            var splitVal = val.split('.');
            if (splitVal.length == 2 && splitVal[1].length > decimal) {
                // user entered invalid input
                $(ele).val(splitVal[0] + '.' + splitVal[1].substr(0, decimal));
            }
        } else if (decimal == 0) {
            // do not allow decimal place
            var splitVal = val.split('.');
            if (splitVal.length > 1) {
                // user entered invalid input
                $(ele).val(splitVal[0]); // always trim everything after '.'
            }
        }
    }
}
function Delete_waterflow(ss) {
    if (confirm("Are you sure you want to Delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_waterflowdata",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                click_waterflow += 1;
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }
                PageNumber_waterflow = PageNumber_waterflow;
                if (PageNumber_waterflow == 1) {
                    sno_waterflow = 0;
                    countwaterflow = 0;
                } else {
                    var ssd = (PageNumber_waterflow - 1);
                    var sdsd = ssd * 100;
                    sno_waterflow = sdsd;
                }
                totalwaterflow = 0;
                watertotal();
            }
        });
    }
}
