function Update_data_waterflow(id, RowNo) {

    var i = 0;
    var id = id;

    var latitude = $('#latitude_waterflow' + RowNo).val();
    var longitude = $('#longitude_waterflow' + RowNo).val();
    var village = $('#village' + RowNo).val();
    var locationdetail = $('#locationdetail' + RowNo).val();
    var AreaIrrigated = $('#AreaIrrigated' + RowNo).val();
    var OwnerName = $('#OwnerName' + RowNo).val();
    var WaterFlowMeter_Installation_Date = $('#WaterFlowMeter_Installation_Date' + RowNo).val();
    var Meterid = $('#Meterid' + RowNo).val();
    var DateofEntry = $('#DateofEntry' + RowNo).val();
    var depthofwell = $('#depthofwell' + RowNo).val();
    var WellType = $('#WellType' + RowNo).val();

    if (latitude == "") {
        alert("Please Enter latitude");
        i = 1;
    }
    else if (longitude == "") {

        alert("Please Enter longitude");
        i = 1;
    }
    else if (village == "" || village == null) {

        alert("Please Enter Village Name");
        i = 1;
    }
    else if (locationdetail == "" || locationdetail == null) {

        alert("Please Enter Location Details");
        i = 1;
    }
    else if (DateofEntry == "" || DateofEntry == null) {

        alert("Please Enter Date of Entry");
        i = 1;
    }
    else if (AreaIrrigated == "" || AreaIrrigated == null) {

        alert("Please Enter Area Irrigated(ha)");
        i = 1;
    }
    else if (depthofwell == "" || depthofwell == null) {

        alert("Please Enter Depth of Well(mbmp)");
        i = 1;
        return false;
    }
    else if (WaterFlowMeter_Installation_Date == "" || WaterFlowMeter_Installation_Date == null) {

        alert("Please Enter WaterFlow Meter_Installation Date");
        i = 1;
    }
    else if (OwnerName == "" || OwnerName == null) {

        alert("Please Enter Name of the owner");
        i = 1;
    }
    else if (Meterid == "" || Meterid == null) {

        alert("Please Enter Meter id");
        i = 1;
    }

    var data = "";

    if (meterid != Meterid) {
        if (i == 0) {
            if (confirm("Are you sure you want to Update this entry?")) {
                $.ajax({
                    type: "POST",
                    contentType: "application/json;charset=utf-8",
                    url: "/GplevelMobileData/check_meterid",
                    data: "{'Meterid': '" + Meterid + "'}",
                    dataType: 'JSON',
                    success: function (response) {

                        data = response;
                        if (data == "Verified") {

                        } else {
                            alert(response);
                        }
                        if (data == "Verified") {


                            var formdata = new FormData();
                            formdata.append("id", id);
                            formdata.append("village", village);
                            formdata.append("locationdetail", locationdetail);
                            formdata.append("latitude", latitude);
                            formdata.append("longitude", longitude);
                            formdata.append("AreaIrrigated", AreaIrrigated);
                            formdata.append("depthofwell", depthofwell);
                            formdata.append("OwnerName", OwnerName);
                            formdata.append("DateofEntry", DateofEntry);
                            formdata.append("Meterid", Meterid);
                            formdata.append("WaterFlowMeter_Installation_Date", WaterFlowMeter_Installation_Date);

                            $.ajax({
                                url: '/GplevelMobileData/Update_waterflow',
                                data: formdata,
                                type: 'POST',
                                contentType: false,
                                processData: false,
                                success: function (response) {

                                    alert(response);
                                    if (response == "SessionTimeOut") {
                                          window.location = "/Home/LogOut";
                                    }
                                    else if (response == "Updated Successfully") {
                                        PageNumber_waterflow = PageNumber_waterflow;
                                        if (PageNumber_waterflow == 1) {
                                            countwaterflow = 0;
                                            countexe = 0;
                                        } else {
                                            var ssd = (PageNumber_waterflow - 1);
                                            var sdsd = ssd * 100;
                                            sno_waterflow = sdsd;
                                        }

                                        totalwaterflow = 0;
                                        watertotal();
                                        meterid = "";
                                    }
                                    else {
                                        $('.loader').hide();
                                    }
                                },
                                error: function () {
                                    alert('Update Failed');
                                }
                            });
                        }

                    }
                });
            }
        }
    }
    else {



        var formdata = new FormData();
        formdata.append("id", id);
        formdata.append("village", village);
        formdata.append("locationdetail", locationdetail);
        formdata.append("latitude", latitude);
        formdata.append("longitude", longitude);
        formdata.append("AreaIrrigated", AreaIrrigated);
        formdata.append("depthofwell", depthofwell);
        formdata.append("OwnerName", OwnerName);
        formdata.append("DateofEntry", DateofEntry);
        formdata.append("Meterid", Meterid);
        formdata.append("WellType", WellType);
        formdata.append("WaterFlowMeter_Installation_Date", WaterFlowMeter_Installation_Date);
        if (confirm("Are you sure you want to Update this entry?")) {
            $.ajax({
                url: '/GplevelMobileData/Update_waterflow',
                data: formdata,
                type: 'POST',
                contentType: false,
                processData: false,
                success: function (response) {

                    alert(response);
                    if (response == "SessionTimeOut") {
                          window.location = "/Home/LogOut";
                    }
                    else if (response == "Updated Successfully") {
                        PageNumber_waterflow = PageNumber_waterflow;
                        if (PageNumber_waterflow == 1) {
                            countwaterflow = 0;
                            countexe = 0;
                        } else {
                            sno_waterflow -= close_length_waterflow;

                        }
                        //PageNumber_waterflow = 1;
                        //sno_waterflow = 0;
                        //countwaterflow = 0;
                        totalwaterflow = 0;
                        watertotal();
                        meterid = "";
                    }
                    else {
                        $('.loader').hide();
                    }
                },
                error: function () {
                    alert('Update Failed');
                }
            });
        }

    }

}
