var reading = 0;

function editrowcomp_A_Good_waterflowdata(i) {

    $('#AWP1_TR_data_waterflow' + i).hide();
    $('#Hide_AWP1_TR_data_waterflow' + i).show();
}
function cancelcomp_A_Support_NEW_datawaterflow(i) {
    /*reading = $('#MeterReading' + i).val();*/
    $('#AWP1_TR_data_waterflow' + i).show();
    $('#Hide_AWP1_TR_data_waterflow' + i).hide();

}
function Update_waterflow_data(ss, RowNo) {

    var i = 0;
    var id = ss;
    var red = reading;
    var MeterReading = $('#MeterReading' + RowNo).val();


    if (MeterReading == "") {

        alert("Please Enter Water Flow Reading ");
        i = 1;
    }
    //else if (red > MeterReading) {
    //    alert("current reading cannot be smaller than previous reading ");
    //    i = 1;
    //}
    if (i == 0) {

        if (confirm("Are you sure you want to Update this entry?")) {
            var formdata = new FormData();
            formdata.append("id", id);
            formdata.append("MeterReading", MeterReading);

            $.ajax({
                url: '/GplevelMobileData/Update_waterflow_data',
                data: formdata,
                type: 'POST',
                contentType: false,
                processData: false,
                success: function (response) {

                    alert(response);
                    if (response == "SessionTimeOut") {
                          window.location = "/Home/LogOut";
                    }

                    find_waterflow_data(iddwaterflow);
                },
                error: function () {
                    alert('Update Failed');
                }
            });
        }
    }
}
function Delete_waterflow_data(ss) {
    if (confirm("Are you sure you want to Delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_waterflow_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);

                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_waterflow_data(iddwaterflow);
            }
        });
    }
}
function submit_spmu_waterflow_data(ss) {
    if (confirm("Are you sure you want to Submit this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/submit_spmu_waterflow_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Successfully Submitted" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_waterflow_data(iddwaterflow);
            }
        });
    }
}
function approve_spmu_waterflow_data(ss) {
    if (confirm("Are you sure you want to Approve this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/approve_waterflow_data_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Approved Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_waterflow_data(iddwaterflow);
            }
        });
    }
}
function reject_spmu_waterflow_data(ss, i) {
    var remark = $('#remarks_status_waterflow' + i).val();
    if (remark == "") {
        alert("Please Enter Remark");
        return false;
    }
    if (confirm("Are you sure you want to Reject this entry?")) {
        var obj = {};
        obj.id = ss;
        obj.reject_remark = remark;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/reject_waterflow_data_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Rejected Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_waterflow_data(iddwaterflow);

            }
        });
    }
}


