function Delete_rainfall(ss) {
    if (confirm("Are you sure you want to Delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_rainfall",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                click_rainfall += 1;
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }
                PageNumber_rain = PageNumber_rain;
                if (PageNumber_rain == 1) {
                    sno_rain = 0;
                    countrain = 0;
                } else {
                    var ssd = (PageNumber_rain - 1);
                    var sdsd = ssd * 100;
                    sno_rain = sdsd;
                }

                //sno_rain = 0;
                //countrain = 0;
                totalrainss = 0;
                raintotal();
            }
        });
    }
}
