function Delete_quality(ss) {
    if (confirm("Are you sure you want to Delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_quality",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                click_button_quality += 1;

                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }
                PageNumberwater = PageNumberwater;
                if (PageNumberwater == 1) {
                    swater = 0;
                    countwater = 0;
                } else {
                    var ssd = (PageNumberwater - 1);
                    var sdsd = ssd * 100;
                    swater = sdsd;
                }

                //PageNumberwater = 1;
                //swater = 0;
                //countwater = 0;
                totalwaterss = 0;
                totalwater();
            }
        });
    }
}
