function enforceNumberValidation_quality(i, ele) {

    let j = i.toString();
    /*var i = aaa;*/
    var match = false;
    var match2 = false;
    var matchwr = false;
    var matchwr2 = false;
    var lat = $('#latitude_quality' + j).val();
    var long = $('#longitude_quality' + j).val();




    if (!(lat.indexOf(".") == -1)) {
        match = true; // decimal
    } else {
        match = false;
    }
    if (lat.length == 2 && match != true) {
        $('#latitude_quality' + j).val(lat + '.');
    } else if (lat.length == 1 && match != false) {
        $('#latitude_quality' + j).val('');
    }


    if (!(long.indexOf(".") == -1)) {
        match2 = true; // decimal
    } else {
        match2 = false;
    }
    if (long.length == 2 && match2 != true) {
        $('#longitude_quality' + j).val(long + '.');
    } else if (long.length == 1 && match2 != false) {
        $('#longitude_quality' + j).val('');
    }


    var latwr = $('#latitude_quality' + j).val();
    var longwr = $('#longitude_quality' + j).val();

    if (!(latwr.indexOf(".") == -1)) {
        matchwr = true; // decimal
    } else {
        matchwr = false;
    }
    if (latwr.length == 2 && matchwr != true) {
        $('#latitude_quality' + j).val(latwr + '.');
    } else if (latwr.length == 1 && matchwr != false) {
        $('#latitude_quality' + j).val('');
    }


    if (!(longwr.indexOf(".") == -1)) {
        matchwr2 = true; // decimal
    } else {
        matchwr2 = false;
    }
    if (longwr.length == 2 && matchwr2 != true) {
        $('#longitude_quality' + j).val(longwr + '.');
    } else if (longwr.length == 1 && matchwr2 != false) {
        $('#longitude_quality' + j).val('');
    }


    if ($(ele).data('decimal') != null) {
        // found valid rule for decimal
        var decimal = parseInt($(ele).data('decimal')) || 0;
        var val = $(ele).val();
        if (decimal > 0) {
            var splitVal = val.split('.');
            if (splitVal.length == 2 && splitVal[1].length > decimal) {
                // user entered invalid input
                $(ele).val(splitVal[0] + '.' + splitVal[1].substr(0, decimal));
            }
        } else if (decimal == 0) {
            // do not allow decimal place
            var splitVal = val.split('.');
            if (splitVal.length > 1) {
                // user entered invalid input
                $(ele).val(splitVal[0]); // always trim everything after '.'
            }
        }
    }
}

function Value_change_wq(selectElement, index) {
    var selectedValue = $(selectElement).val();
    if (selectedValue == "Others") {
        $("#Hide_AWP1_TR_quality" + index).find("#others" + index).prop("disabled", false);

    }
    else {
        $("#Hide_AWP1_TR_quality" + index).find("#others" + index).prop("disabled", true);
    }
}


function editrowcomp_A_Good4_quality(i) {
    var gp_name = $('#gp' + i).val();
    var village = $('#village' + i).val();
    var obj = {};
    obj.gram_panchayat_name = gp_name;
    $.ajax({
        type: "POST",
        contentType: "application/json;charset=utf-8",
        url: "/GplevelMobileData/village_name",
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (response) {
            if (response == "Logout") {
                  window.location = "/Home/LogOut";
            }
            var optionhtml = '';
            // var optionhtml = '<option value="' + village + '">' + village + '</option>';
            if (response.length != 0) {
                allstate = [];
                FullData = response;
                var ddlSourse = {};
                for (var j = 0; j < response.length; j++) {
                    if (response[j].village_name != null && response[j].village_name != "") {
                        if (!ddlSourse[response[j].village_name]) {
                            if (response[j].village_name != village) {
                                optionhtml += '<option value="' + response[j].village_name + '">' + response[j].village_name + '</option>';
                                allstate.push(response[j].village_name);
                                ddlSourse[response[j].village_name] = response[j].village_name;
                            }
                        }
                    }
                }
                $('#village' + i).append(optionhtml);


            }

        }
    });
    $('#AWP1_TR_quality' + i).hide();
    $('#Hide_AWP1_TR_quality' + i).show();
}
function cancelcomp_A_Support_NEW_quality(i) {
    $('#AWP1_TR_quality' + i).show();
    $('#Hide_AWP1_TR_quality' + i).hide();

}
function Update_data_quality(id, RowNo) {
    debugger;
    var i = 0;
    var id = id;

    var latitude = $('#latitude_quality' + RowNo).val();
    var longitude = $('#longitude_quality' + RowNo).val();
    var well_depth_mbgl = $('#well_depth_mbgl' + RowNo).val();
    var village = $('#village' + RowNo).val();
    var location_details = $('#location_details' + RowNo).val();
    var typeofwell = $('#type_of_well' + RowNo).val();
    var other_well_type = $('#others' + RowNo).val();


    if (latitude == "") {
        alert("Please Enter latitude");
        i = 1;
    }
    else if (longitude == "") {

        alert("Please Enter longitude");
        i = 1;
    }
    else if (well_depth_mbgl == "") {

        alert("Please Enter Well Depth (m bgl)");
        i = 1;
    }
    else if (village == "" || village == null) {

        alert("Please Enter Village Name");
        i = 1;
    }
    else if (location_details == "" || location_details == null) {

        alert("Please Enter Location Details");
        i = 1;
    }


    if (i == 0) {

        if (confirm("Are you sure you want to Update this entry?")) {
            var formdata = new FormData();
            formdata.append("id", id);
            formdata.append("latitude", latitude);
            formdata.append("longitude", longitude);
            formdata.append("well_depth_mbgl", well_depth_mbgl);
            formdata.append("village", village);
            formdata.append("location_details", location_details);
            formdata.append("typeofwell", typeofwell);
            formdata.append("other_well_type", other_well_type);

            $.ajax({
                url: '/GplevelMobileData/Update_quality',
                data: formdata,
                type: 'POST',
                contentType: false,
                processData: false,
                success: function (response) {

                    alert(response);
                    if (response == "SessionTimeOut") {
                          window.location = "/Home/LogOut";
                    }
                    else if (response == "Updated Successfully") {
                        PageNumberwater = PageNumberwater;
                        if (PageNumberwater == 1) {
                            swater = 0;
                        } else {
                            var ssd = (PageNumberwater - 1);
                            var sdsd = ssd * 100;
                            swater = sdsd;
                        }
                        //PageNumberwater = 1;
                        //swater = 0;
                        //countwater = 0;
                        totalwaterss = 0;
                        totalwater();
                    }
                    else {
                        $('.loader').hide();
                    }
                },
                error: function () {
                    alert('Update Failed');
                }
            });
        }
    }
}

