function Update_quality_data(ss, RowNo) {

    var i = 0;
    var data_id = ss;
    var ph = $('#ph' + RowNo).val();
    var total_hardness_mgl = $('#total_hardness_mgl' + RowNo).val();
    var alkalinity_mgl = $('#alkalinity_mgl' + RowNo).val();
    var nitrate_mgl = $('#nitrate_mgl' + RowNo).val();
    var fluoride_mgl = $('#fluoride_mgl' + RowNo).val();
    var iron_mgl = $('#iron_mgl' + RowNo).val();
    var ec_us_cm = $('#ec_us_cm' + RowNo).val();
    var chloride = $('#chloride' + RowNo).val();
    var free_chlorine = $('#free_chlorine' + RowNo).val();
    var turbudity = $('#turbudity' + RowNo).val();
    var tds = $('#tds' + RowNo).val();
    var bacterial_test = $('#bacterial_test' + RowNo).val();

    if (ph == "") {
        alert("Please Enter pH ")
        return false;
    }
    else if (total_hardness_mgl == null || total_hardness_mgl == "null") {
        total_hardness_mgl = "";
    }
    else if (alkalinity_mgl == null || alkalinity_mgl == "null") {
        alkalinity_mgl = "";
    }
    else if (nitrate_mgl == "") {
        alert("Please Enter Nitrate(mg/L) ")
        return false;
    }
    else if (fluoride_mgl == "") {
        alert("Please Enter Fluoride(mg/L) ")
        return false;
    }
    else if (iron_mgl == null || iron_mgl == "null") {
        iron_mgl = "";
    }
    else if (ec_us_cm == null || ec_us_cm == "null") {
        ec_us_cm = "";
    }
    else if (chloride == null || chloride == "null") {
        chloride = "";
    }
    else if (free_chlorine == null || free_chlorine == "null") {
        free_chlorine = "";
    }
    else if (turbudity == null || turbudity == "null") {
        turbudity = "";
    }
    else if (tds == null || tds == "null") {
        tds = "";
    }
    else if (bacterial_test == null || bacterial_test == "null") {
        bacterial_test = "";
    }

    if (i == 0) {
        if (confirm("Are you sure you want to Update this entry?")) {
            var formdata = new FormData();
            formdata.append("data_id", data_id);
            formdata.append("ph", ph);
            formdata.append("total_hardness_mgl", total_hardness_mgl);
            formdata.append("alkalinity_mgl", alkalinity_mgl);
            formdata.append("nitrate_mgl", nitrate_mgl);
            formdata.append("fluoride_mgl", fluoride_mgl);
            formdata.append("iron_mgl", iron_mgl);
            formdata.append("chloride", chloride);
            formdata.append("ec_us_cm", ec_us_cm);
            formdata.append("free_chlorine", free_chlorine);
            formdata.append("turbudity", turbudity);
            formdata.append("tds", tds);
            formdata.append("bacterial_test", bacterial_test);

            $.ajax({
                url: '/GplevelMobileData/Update_quality_data',
                data: formdata,
                type: 'POST',
                contentType: false,
                processData: false,
                success: function (response) {

                    alert(response);
                    if (response == "SessionTimeOut") {
                          window.location = "/Home/LogOut";
                    }
                    else if (response == "Updated Successfully") {

                        find_quality_data(iddquality);
                    }
                    else {
                        $('.loader').hide();
                    }
                },
                error: function () {
                    alert('Update Failed');
                }
            });
        }
    }
}
function Delete_quality_data(ss) {
    if (confirm("Are you sure you want to Delete this entry?")) {
        var obj = {};
        obj.data_id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_quality_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);

                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_quality_data(iddquality);
            }
        });
    }
}
function submit_spmu_quality_data(ss) {
    if (confirm("Are you sure you want to Submit this entry?")) {
        var obj = {};
        obj.data_id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/submit_spmu_quality_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Successfully Submitted" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_quality_data(iddquality);
            }
        });
    }
}
function approve_spmu_quality_data(ss) {
    if (confirm("Are you sure you want to Approve this entry?")) {
        var obj = {};
        obj.data_id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/approve_quality_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Approved Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_quality_data(iddquality);
            }
        });
    }
}
function reject_spmu_quality_data(ss, i) {
    var remark = $('#remarks_status_quality_data' + i).val();
    if (remark == "") {
        alert("Please Enter Remark");
        return false;
    }
    if (confirm("Are you sure you want to Reject this entry?")) {
        var obj = {};
        obj.data_id = ss;
        obj.reject_remark = remark;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/reject_quality_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Rejected Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_quality_data(iddquality);
            }
        });
    }
}


