function Delete_geo(ss) {
    if (confirm("Are you sure you want to Delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_geodata",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                click_geo += 1
                if (response == "Logout") {
                      window.location = "/Home/LogOut";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }
                PageNumbergeo = PageNumbergeo;
                if (PageNumbergeo == 1) {
                    sgeo = 0;
                    countwell = 0;
                } else {
                    var ssd = (PageNumbergeo - 1);
                    var sdsd = ssd * 100;
                    sgeo = sdsd;
                    click_geo = 0;
                }
                //PageNumbergeo = 1;
                //sgeo = 0;
                //countgeo = 0;
                totalgeoss = 0;
                totalgeo();
            }
        });
    }
}
